from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
import reversion
from reversion.models import Version
from .models import Document

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def rollback_document_version(request):
    version_id = request.data.get('version_id')
    try:
        version = Version.objects.get(id=version_id)
    except Version.DoesNotExist:
        return Response({'error': 'Version record not found'}, status=status.HTTP_404_NOT_FOUND)

    # Verify that the underlying object exists and belongs to the authenticated user's workspace
    doc = Document.objects.filter(id=version.object_id, workspace=request.user.workspace).first()
    if not doc:
        return Response({'error': 'Document not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

    with reversion.create_revision():
        reversion.set_user(request.user)
        reversion.set_comment(f"Rollback requested by user {request.user.id}")
        version.revision.revert(delete=True)

    return Response({'status': 'reverted', 'object_id': version.object_id})
